toolScript:
let stressInterval = null;
        // Initialize Visualizer Bars
        const wave = document.getElementById('visual-wave');
        for (let i = 0; i < 30; i++) {
            const bar = document.createElement('div');
            bar.className = 'wave-bar';
            wave.appendChild(bar);
        }
        function animateWave(active) {
            const bars = document.querySelectorAll('.wave-bar');
            const icon = document.getElementById('device-icon');
            if (active) {
                icon.classList.add('vibrating-ui');
                bars.forEach((bar, idx) => {
                    bar.style.height = `${30 + Math.random() * 80}px`;
                    bar.style.backgroundColor = '#a855f7';
                });
            } else {
                icon.classList.remove('vibrating-ui');
                bars.forEach(bar => {
                    bar.style.height = '25px';
                    bar.style.backgroundColor = '#334155';
                });
            }
        }
        function testVibrate(pattern) {
            if ("vibrate" in navigator) {
                navigator.vibrate(pattern);
                // Visual sync logic
                let duration = pattern.reduce((a, b) => a + b, 0);
                animateWave(true);
                setTimeout(() => animateWave(false), duration);
            } else {
                checkCompatibility();
            }
        }
        function runCustom() {
            const str = document.getElementById('custom-pattern').value;
            const pattern = str.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n));
            if (pattern.length > 0) {
                testVibrate(pattern);
                showToast("Custom pattern executed.");
            } else {
                showToast("Invalid string format.");
            }
        }
        function toggleStressTest() {
            const btn = document.getElementById('stress-btn');
            const statusIcon = document.getElementById('btn-status-icon');
            if (stressInterval) {
                // Stop
                clearInterval(stressInterval);
                stressInterval = null;
                navigator.vibrate(0);
                animateWave(false);
                btn.querySelector('span').innerText = "START CONTINUOUS STRESS TEST";
                btn.classList.replace('bg-red-600', 'bg-slate-900');
                btn.classList.replace('border-red-800', 'border-slate-700');
                statusIcon.classList.remove('animate-ping', 'bg-red-200');
                statusIcon.classList.add('bg-purple-400');
                showToast("Stress test terminated.");
            } else {
                // Start
                if (!("vibrate" in navigator)) return checkCompatibility();
                btn.querySelector('span').innerText = "HALT STRESS TEST";
                btn.classList.replace('bg-slate-900', 'bg-red-600');
                btn.classList.replace('border-slate-700', 'border-red-800');
                statusIcon.classList.add('animate-ping', 'bg-red-200');
                animateWave(true);
                stressInterval = setInterval(() => {
                    navigator.vibrate(500);
                }, 600);
                showToast("Continuous stress cycle active.");
            }
        }
        function checkCompatibility() {
            const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
            if (isIOS) {
                document.getElementById('ios-warning').classList.remove('hidden');
                window.scrollTo({ top: document.getElementById('ios-warning').offsetTop - 50, behavior: 'smooth' });
            } else {
                showToast("Hardware API Unsupported on this browser.");
            }
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // --- SCROLL LOGIC ---
        document.addEventListener('DOMContentLoaded', () => {
            if (!("vibrate" in navigator)) {
                console.log("Hardware Transducer API Offline");
            }
        });
